export default function readRequest({ update }) {
  const message = update?.message;
  if (!message || typeof message.text !== 'string' || !message.text.trim()) throw new Error('Send a nonempty text song request.');
  if (!Number.isSafeInteger(message.chat?.id)) throw new Error('The Telegram message has no valid chat ID.');
  return { text: message.text, chatId: message.chat.id };
}

