export default function chooseTrack({ tracks }) {
  if (!tracks || typeof tracks !== 'object' || !Array.isArray(tracks.items)) throw new Error('Spotify search did not return a track list.');
  const first = tracks.items[0];
  if (first === undefined) return { found: false, track: null };
  if (!first || typeof first !== 'object' || Array.isArray(first)) throw new Error('The first search result must be a track object.');
  return { found: true, track: first };
}

