export default function prepareQueueItem({ track }) {
  if (!track || typeof track.id !== 'string' || !/^[A-Za-z0-9]+$/.test(track.id)) throw new Error('The selected track has no valid ID.');
  return { uri: 'spotify:track:' + track.id };
}

