export default function formatReply({ mode, playback }) {
  const failures = {
    search: 'Spotify search failed. No playback commands were attempted.',
    queue: 'Spotify could not confirm adding the track to the queue. Check Spotify before repeating the request.',
    skip: 'Spotify could not confirm skipping to the next track. An earlier queue command may already have completed.',
    current: 'Playback commands were sent, but the current state could not be read. Check Spotify before repeating the request.',
  };
  let text, status;
  if (mode === 'not_found') { text = 'Song not found.'; status = 'not_found'; }
  else if (Object.hasOwn(failures, mode)) { text = failures[mode]; status = 'failed'; }
  else if (mode === 'observed') {
    if (playback !== null && (!playback || typeof playback !== 'object' || Array.isArray(playback) || playback.error)) throw new Error('Invalid Spotify playback response.');
    if (playback?.is_playing !== undefined && typeof playback.is_playing !== 'boolean') throw new Error('Invalid Spotify play/pause status.');
    const item = playback?.item;
    if (item == null) {
      text = 'Playback commands were sent, but Spotify reported no current item.'; status = 'unavailable';
    } else {
      if (typeof item.name !== 'string' || !item.name) throw new Error('The current Spotify item has no title.');
      const artists = Array.isArray(item.artists) ? item.artists.map(artist => artist?.name).filter(name => typeof name === 'string' && name) : [];
      const album = typeof item.album?.name === 'string' ? item.album.name : '';
      const state = playback.is_playing === true ? 'playing' : playback.is_playing === false ? 'paused' : 'unknown';
      text = 'Spotify reports: ' + item.name + (artists.length ? ' — ' + artists.join(', ') : '') + (album ? '\nAlbum: ' + album : '') + '\nPlayback: ' + state;
      status = 'observed';
    }
  } else throw new Error('Unknown Spotify reply mode.');
  const reply = text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  if (reply.length > 4096) throw new Error('The Spotify status exceeds Telegram’s message limit.');
  return { reply, status };
}

